changeSet.sql:
ALTER TABLE transactions ADD COLUMN penalties_refundable boolean;
COMMENT ON COLUMN transactions.penalties_refundable IS
    'Copied at Proceed to buy for an instalment purchase: whether its late-payment penalties are refunded on withdrawal. Null for outright purchases.';

CREATE TABLE transaction_penalty_steps (
    id              uuid NOT NULL PRIMARY KEY,
    created_at      timestamp(6) with time zone NOT NULL,
    created_by      varchar(255),

    transaction_id  uuid NOT NULL REFERENCES transactions (id),
    months_late     integer NOT NULL,
    penalty_pct     numeric(5, 2) NOT NULL,

    CONSTRAINT uq_transaction_penalty_steps UNIQUE (transaction_id, months_late),
    CONSTRAINT chk_transaction_penalty_steps_months CHECK (months_late > 0),
    CONSTRAINT chk_transaction_penalty_steps_pct CHECK (penalty_pct >= 0 AND penalty_pct <= 100)
);
REVOKE UPDATE, DELETE, TRUNCATE ON transaction_penalty_steps FROM ${appDbUsername};
COMMENT ON TABLE transaction_penalty_steps IS
    'The estate''s declared late-payment steps as offered to this buyer: months late -> % of the overdue instalment. The highest step reached applies. Never changed.';

ALTER TABLE payments
    ADD COLUMN penalty_amount numeric(19, 4) NOT NULL DEFAULT 0,
    ADD CONSTRAINT chk_payments_penalty_amount CHECK (penalty_amount >= 0);
COMMENT ON COLUMN payments.penalty_amount IS
    'Late-payment penalties charged in this payment, fixed when it started (the lines are in payment_penalties). Part of amount.';

CREATE TABLE payment_penalties (
    id                  uuid NOT NULL PRIMARY KEY,
    created_at          timestamp(6) with time zone NOT NULL,
    created_by          varchar(255),

    payment_id          uuid NOT NULL REFERENCES payments (id),
    instalment_sequence integer NOT NULL,
    months_late         integer NOT NULL,
    penalty_pct         numeric(5, 2) NOT NULL,
    amount              numeric(19, 4) NOT NULL,

    CONSTRAINT uq_payment_penalties UNIQUE (payment_id, instalment_sequence),
    CONSTRAINT chk_payment_penalties_amount CHECK (amount > 0)
);
CREATE INDEX idx_payment_penalties_payment ON payment_penalties (payment_id);
REVOKE UPDATE, DELETE, TRUNCATE ON payment_penalties FROM ${appDbUsername};
COMMENT ON TABLE payment_penalties IS
    'One line per overdue instalment a payment carried a penalty for: the step reached when the buyer started paying, and its amount. Never changed.';

changeSet.rollback:
DROP TABLE payment_penalties;
ALTER TABLE payments
    DROP CONSTRAINT chk_payments_penalty_amount,
    DROP COLUMN penalty_amount;

changeSet.sql:
CREATE TABLE instalment_reminders ( id uuid NOT NULL PRIMARY KEY, created_at timestamp(6) with time zone NOT NULL, created_by varchar(255),
transaction_id uuid NOT NULL REFERENCES transactions (id), schedule_version integer NOT NULL, instalment_sequence integer NOT NULL, stage varchar(32) NOT NULL,
CONSTRAINT uq_instalment_reminders UNIQUE (transaction_id, schedule_version, instalment_sequence, stage), CONSTRAINT chk_instalment_reminders_stage CHECK (stage IN ('SEVEN_DAYS_BEFORE', 'ONE_DAY_BEFORE', 'OVERDUE', 'IN_ARREARS')) ); REVOKE UPDATE, DELETE, TRUNCATE ON instalment_reminders FROM ${appDbUsername}; COMMENT ON TABLE instalment_reminders IS 'Which instalment reminders were sent: 7 days and 1 day before the due date, on the first day overdue, and on entering arrears (day 8). One per instalment and stage.';
